let CTX = null;
const freePort = (n, speed, used = []) => n.ports.findIndex((p, i) => !p.link && !p.service && !p.reserved && p.medium === 'Ethernet' && p.speed === speed && !isMgmtPort(p) && !used.includes(p) && !officeUses(CTX, n, i));
